// Generated by forge. Package manager policies of npm, pnpm and Yarn (run by
// .forge/check.sh with bun, through forge_helper). Usage:
//   bun pm_policy.mjs <forge-tmp> <mode>
// Modes (the change is <forge-tmp>/changed, base copies under <forge-tmp>/base/):
//   npm-cooldown <s>    .npmrc min-release-age is at least <s> seconds in days (3), and package.json requires
//                       npm >= 11.10 (devEngines.packageManager or packageManager): older npm ignores it
//   npm-scripts         package.json allowScripts gains no approval; .npmrc gains no
//                       ignore-scripts=false, allow-scripts entry or dangerously-allow-all-scripts
//   pnpm-builds         pnpm-workspace.yaml gains no allowBuilds approval or onlyBuiltDependencies
//                       entry, dangerouslyAllowAllBuilds is not turned on, strictDepBuilds and
//                       blockExoticSubdeps are not turned off
//   yarn-scripts        .yarnrc.yml enableScripts is not turned on; package.json
//                       dependenciesMeta gains no built: true
//   pnpm-workspace      a changed package.json depends on a workspace package with workspace:
//   pnpm-catalog        a dependency added or changed in a package.json whose name is in the
//                       catalog (or a named catalog) uses catalog: (unless catalogMode is strict)
//   pnpm-overrides      pnpm-workspace.yaml overrides entries new since the base
// Exit 0: nothing found; 1: findings printed ("path:line message", or "path: message" for a
// requirement of the whole setup); 3: cannot run ("skipped: …" printed).
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const [tmp, mode, cooldownArg] = process.argv.slice(2);
// npm-cooldown: Forge's one release cooldown, in seconds (FORGE_COOLDOWN_SECONDS), as days
const cooldownDays = Math.ceil(Number(cooldownArg) / 86400);
const lines = (name) => {
  try { return readFileSync(join(tmp, name), "utf8").split("\n").filter(Boolean); } catch { return []; }
};
const changed = new Set(lines("changed"));
const inbase = new Set(lines("inbase"));
const readNow = (p) => { try { return readFileSync(p, "utf8"); } catch { return null; } };
const readBase = (p) => {
  if (!changed.has(p)) return readNow(p);
  if (!inbase.has(p)) return null;
  try { return readFileSync(join(tmp, "base", p), "utf8"); } catch { return null; }
};
const findings = [];
const out = (s) => findings.push(s);
const obj = (v) => (v && typeof v === "object" && !Array.isArray(v) ? v : {});
const list = (v) => (Array.isArray(v) ? v : []);

function skip(why) {
  console.log(`skipped: ${why}`);
  process.exit(3);
}
function json(text, path) {
  if (text === null) return {};
  try { return obj(JSON.parse(text)); } catch { skip(`${path} is not valid JSON`); }
}
function yaml(text, path) {
  if (text === null) return {};
  if (typeof Bun === "undefined" || !Bun.YAML) skip("bun 1.2.21 or later is needed to read YAML");
  try { return obj(Bun.YAML.parse(text)); } catch { skip(`${path} is not valid YAML`); }
}
/** .npmrc: key -> list of values (a key may be set several times; key[] appends). */
function npmrc(text) {
  const m = new Map();
  for (const raw of (text ?? "").split(/\r?\n/)) {
    const l = raw.trim();
    if (!l || l.startsWith("#") || l.startsWith(";")) continue;
    const i = l.indexOf("=");
    if (i < 0) continue;
    const k = l.slice(0, i).trim().replace(/\[\]$/, "");
    let v = l.slice(i + 1).trim();
    if (/^(["']).*\1$/.test(v)) v = v.slice(1, -1);
    m.set(k, [...(m.get(k) ?? []), v]);
  }
  return m;
}
const last = (m, k) => (m.get(k) ?? []).at(-1);
/** The line (from 1) of the first line matching re, else 0. */
function lineOf(text, re) {
  const i = (text ?? "").split("\n").findIndex((l) => re.test(l));
  return i < 0 ? 0 : i + 1;
}
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const ACCEPT = "the user approves it, not Claude";

// ---- numeric versions

const parts = (v) => String(v).split(".").map((x) => Number.parseInt(x, 10) || 0);
function ge(a, b) {
  const x = parts(a), y = parts(b);
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    if ((x[i] ?? 0) !== (y[i] ?? 0)) return (x[i] ?? 0) > (y[i] ?? 0);
  }
  return true;
}
/** The lowest version a semver range allows (its lower bound), or undefined: ">=11.10", "^11.10.0", "11.10.0", "~11.10". */
function lowest(range) {
  const alts = String(range).split("||").map((r) => r.trim());
  let low;
  for (const r of alts) {
    const m = /^(?:>=|\^|~|=|v)?\s*(\d+(?:\.\d+){0,2})(?:[-+][^\s]*)?(?:\s|$)/.exec(r);
    if (!m) return undefined;
    if (low === undefined || !ge(m[1], low)) low = m[1];
  }
  return low;
}

// ---- modes

function npmCooldown() {
  if (!(cooldownDays > 0)) skip("npm-cooldown needs the cooldown in seconds");
  const rc = npmrc(readNow(".npmrc"));
  const age = last(rc, "min-release-age");
  if (!(age !== undefined && /^\d+(\.\d+)?$/.test(age) && Number(age) >= cooldownDays))
    out(`.npmrc: min-release-age is ${age ?? "unset"}; set min-release-age=${cooldownDays} (days) or more so a freshly published (possibly compromised) version is not installed. Packages you must update sooner go in min-release-age-exclude.`);
  const pkg = json(readNow("package.json"), "package.json");
  const wanted = [];
  for (const e of Array.isArray(obj(pkg.devEngines).packageManager) ? pkg.devEngines.packageManager : [obj(pkg.devEngines).packageManager])
    if (obj(e).name === "npm" && typeof e.version === "string") wanted.push(e.version);
  if (typeof pkg.packageManager === "string" && pkg.packageManager.startsWith("npm@")) wanted.push(pkg.packageManager.slice(4).replace(/\+.*$/, ""));
  const low = wanted.map(lowest);
  if (!low.length || low.some((v) => v === undefined || !ge(v, "11.10.0")))
    out(`package.json: npm is required as ${wanted.length ? wanted.join(", ") : "nothing"}; require npm >= 11.10 (devEngines.packageManager {"name": "npm", "version": ">=11.10.0"}, or packageManager "npm@11.10.0" or later): older npm ignores min-release-age.`);
}

function npmScripts() {
  if (changed.has("package.json")) {
    const before = obj(json(readBase("package.json"), "package.json").allowScripts);
    const text = readNow("package.json");
    const now = obj(json(text, "package.json").allowScripts);
    for (const [k, v] of Object.entries(now))
      if (v !== false && before[k] !== v && !(before[k] !== undefined && before[k] !== false))
        out(`package.json:${lineOf(text, new RegExp(`"${esc(k)}"\\s*:`))} allowScripts approves ${k} (its install scripts would run); ${ACCEPT}`);
  }
  if (changed.has(".npmrc")) {
    const before = npmrc(readBase(".npmrc"));
    const text = readNow(".npmrc");
    const now = npmrc(text);
    if (last(now, "ignore-scripts") === "false" && last(before, "ignore-scripts") !== "false")
      out(`.npmrc:${lineOf(text, /^\s*ignore-scripts\s*=/)} ignore-scripts=false; ${ACCEPT}`);
    if (last(now, "dangerously-allow-all-scripts") === "true" && last(before, "dangerously-allow-all-scripts") !== "true")
      out(`.npmrc:${lineOf(text, /^\s*dangerously-allow-all-scripts\s*=/)} dangerously-allow-all-scripts=true runs every dependency's install scripts; ${ACCEPT}`);
    const names = (m) => new Set((m.get("allow-scripts") ?? []).flatMap((v) => v.split(",")).map((s) => s.trim()).filter(Boolean));
    const had = names(before);
    const added = [...names(now)].filter((n) => !had.has(n));
    if (added.length) out(`.npmrc:${lineOf(text, /^\s*allow-scripts(\[\])?\s*=/)} allow-scripts adds ${added.join(", ")} (their install scripts would run); ${ACCEPT}`);
  }
}

function pnpmBuilds() {
  const p = "pnpm-workspace.yaml";
  if (!changed.has(p)) return;
  const before = yaml(readBase(p), p);
  const text = readNow(p);
  const now = yaml(text, p);
  const at = (key) => `${p}:${lineOf(text, new RegExp(`^\\s*["']?${esc(key)}["']?\\s*:`))}`;
  const ab0 = obj(before.allowBuilds), ab = obj(now.allowBuilds);
  for (const k of Object.keys(ab).filter((k) => ab[k] === true && ab0[k] !== true))
    out(`${at(k)} allowBuilds approves ${k} (its install scripts would run); ${ACCEPT}`);
  const ob0 = new Set(list(before.onlyBuiltDependencies).map(String));
  for (const d of list(now.onlyBuiltDependencies).map(String).filter((d) => !ob0.has(d)))
    out(`${p}:${lineOf(text, new RegExp(`^\\s*-\\s*["']?${esc(d)}["']?\\s*(#.*)?$`))} onlyBuiltDependencies adds ${d} (its install scripts would run); ${ACCEPT}`);
  if (now.dangerouslyAllowAllBuilds === true && before.dangerouslyAllowAllBuilds !== true)
    out(`${at("dangerouslyAllowAllBuilds")} dangerouslyAllowAllBuilds: true runs every dependency's install scripts; ${ACCEPT}`);
  for (const key of ["strictDepBuilds", "blockExoticSubdeps"])
    if (now[key] === false && before[key] !== false) out(`${at(key)} ${key}: false; ${ACCEPT}`);
}

function yarnScripts() {
  if (changed.has(".yarnrc.yml")) {
    const text = readNow(".yarnrc.yml");
    const now = yaml(text, ".yarnrc.yml");
    const before = yaml(readBase(".yarnrc.yml"), ".yarnrc.yml");
    if (now.enableScripts === true && before.enableScripts !== true)
      out(`.yarnrc.yml:${lineOf(text, /^\s*enableScripts\s*:/)} enableScripts: true runs every dependency's install scripts; ${ACCEPT}`);
  }
  for (const p of changed) {
    if (!/(^|\/)package\.json$/.test(p) || /(^|\/)node_modules\//.test(p) || !existsSync(p)) continue;
    const text = readNow(p);
    const now = obj(json(text, p).dependenciesMeta);
    const before = obj(json(readBase(p), p).dependenciesMeta);
    for (const [k, v] of Object.entries(now))
      if (obj(v).built === true && obj(before[k]).built !== true)
        out(`${p}:${lineOf(text, new RegExp(`"${esc(k)}"\\s*:`))} dependenciesMeta lets ${k} build (built: true runs its install scripts); ${ACCEPT}`);
  }
}

const SECTIONS = ["dependencies", "devDependencies", "optionalDependencies", "peerDependencies"];
function deps(pkg) {
  const outd = [];
  for (const s of SECTIONS) for (const [name, spec] of Object.entries(obj(pkg[s]))) if (typeof spec === "string") outd.push({ section: s, name, spec });
  return outd;
}
const manifests = () => [...changed].filter((p) => /(^|\/)package\.json$/.test(p) && !/(^|\/)node_modules\//.test(p) && existsSync(p));
const depLine = (text, d) => lineOf(text, new RegExp(`"${esc(d.name)}"\\s*:\\s*"${esc(d.spec)}"`));

function pnpmWorkspace() {
  const ws = yaml(readNow("pnpm-workspace.yaml"), "pnpm-workspace.yaml");
  const globs = list(ws.packages).map(String);
  if (!globs.length) return;
  const r = spawnSync("git", ["ls-files", "-co", "--exclude-standard", "--", "package.json", "*/package.json"], { encoding: "utf8" });
  if (r.status !== 0) skip("git ls-files failed");
  const inc = globs.filter((g) => !g.startsWith("!")).map((g) => new Bun.Glob(g.replace(/^\.\//, "").replace(/\/$/, "")));
  const exc = globs.filter((g) => g.startsWith("!")).map((g) => new Bun.Glob(g.slice(1).replace(/^\.\//, "").replace(/\/$/, "")));
  const names = new Set();
  for (const f of r.stdout.split("\n").filter(Boolean)) {
    if (/(^|\/)node_modules\//.test(f)) continue;
    const dir = f.includes("/") ? f.slice(0, f.lastIndexOf("/")) : ".";
    // an exclusion like **/test/** also excludes the test directory itself
    if (dir === "." ? !globs.includes(".") : !inc.some((g) => g.match(dir)) || exc.some((g) => g.match(dir) || g.match(`${dir}/x`))) continue;
    const n = json(readNow(f), f).name;
    if (typeof n === "string") names.add(n);
  }
  for (const p of manifests()) {
    const text = readNow(p);
    for (const d of deps(json(text, p)))
      if (names.has(d.name) && !d.spec.includes(":"))
        out(`${p}:${depLine(text, d)} ${d.name} is a package of this workspace: depend on it as "workspace:${d.spec === "*" ? "*" : "^"}" so pnpm links it instead of installing a registry copy`);
  }
}

function pnpmCatalog() {
  const ws = yaml(readNow("pnpm-workspace.yaml"), "pnpm-workspace.yaml");
  if (ws.catalogMode === "strict") return;
  const named = new Map();
  for (const n of Object.keys(obj(ws.catalog))) named.set(n, "catalog:");
  for (const [c, entries] of Object.entries(obj(ws.catalogs))) for (const n of Object.keys(obj(entries))) if (!named.has(n)) named.set(n, c === "default" ? "catalog:" : `catalog:${c}`);
  if (!named.size) return;
  for (const p of manifests()) {
    const text = readNow(p);
    const had = new Set(deps(json(readBase(p), p)).map((d) => `${d.section}\0${d.name}\0${d.spec}`));
    for (const d of deps(json(text, p)))
      if (named.has(d.name) && !d.spec.startsWith("catalog:") && !d.spec.startsWith("workspace:") && !had.has(`${d.section}\0${d.name}\0${d.spec}`))
        out(`${p}:${depLine(text, d)} ${d.name} is in the pnpm catalog: use "${named.get(d.name)}" instead of "${d.spec}" so every package gets the same version`);
  }
}

function pnpmOverrides() {
  const p = "pnpm-workspace.yaml";
  if (!changed.has(p)) return;
  const text = readNow(p);
  const before = obj(yaml(readBase(p), p).overrides);
  const now = obj(yaml(text, p).overrides);
  for (const [k, v] of Object.entries(now))
    if (before[k] !== v)
      out(`${p}:${lineOf(text, new RegExp(`^\\s*["']?${esc(k)}["']?\\s*:`))} overrides ${k} to ${v}: say why (a security fix, an incompatible transitive version); an override can hide a vulnerability or force a version its dependents do not support`);
}

const MODES = { "npm-cooldown": npmCooldown, "npm-scripts": npmScripts, "pnpm-builds": pnpmBuilds, "yarn-scripts": yarnScripts, "pnpm-workspace": pnpmWorkspace, "pnpm-catalog": pnpmCatalog, "pnpm-overrides": pnpmOverrides };
if (!MODES[mode]) skip(`unknown mode ${mode}`);
MODES[mode]();
for (const f of findings) console.log(f);
process.exit(findings.length ? 1 : 0);
